pub const bun = @import("bun");
pub const text_diff = @import("./text_diff.zig");
pub const DiffConfig = struct {
    min_bytes_before_chunking: usize,
    chunk_context_lines: usize,
    enable_ansi_colors: bool,
    truncate_threshold: usize,
    truncate_context: usize,

pub fn default(is_agent: bool, enable_ansi_colors: bool) DiffConfig {
            return DiffConfig{ .min_bytes_before_chunking = (if (is_agent) 0 else (2 * 1024)), .chunk_context_lines = (if (is_agent) 1 else 5), .enable_ansi_colors = enable_ansi_colors, .truncate_threshold = (if (is_agent) (1 * 1024) else (2 * 1024)), .truncate_context = (if (is_agent) 50 else 100) };
    }
};

pub const colors = struct {
    const red = "\x1b[31m";
    const green = "\x1b[32m";
    const yellow = "\x1b[33m";
    const invert = "\x1b[7m";
    const dim = "\x1b[2m";
    const white = "\x1b[97m";
    const reset = "\x1b[0m";
};

pub const Style = struct {
    prefix: []const u8,
    prefix_color: []const u8,
    text_color: []const u8,
};

pub const TextLines = struct {
    text: []const u8,
    lines: usize,
};

pub const ModifiedSeg = struct {
    removed: []const u8,
    inserted: []const u8,
    removed_lines: usize,
    inserted_lines: usize,
};

pub const Segment = union(enum) {
    equal: TextLines,
    removed: TextLines,
    inserted: TextLines,
    modified: ModifiedSeg,
    skipped: usize,
};

pub const Printer = struct {
    allocator: std.mem.Allocator,
    out: std.ArrayListUnmanaged(u8),
    colors: bool,
    limit: usize,
    config: DiffConfig,
    chars: text_diff.CharDiff,
    __cp_dropped: bool = false,

pub fn init(allocator: std.mem.Allocator, cap: usize, config: DiffConfig) Printer {
            var out = std.ArrayListUnmanaged(u8).empty;
            _ = &out;
            _ = bun.handleOom(out.ensureTotalCapacity(allocator, cap));
            return Printer{ .allocator = allocator, .out = out, .colors = config.enable_ansi_colors, .limit = @max(config.truncate_threshold, (config.truncate_context * 2)), .config = config, .chars = text_diff.CharDiff.init(allocator) };
    }

pub fn __cp_deinit(self: *Printer) void {
        if (self.__cp_dropped) return;
        self.__cp_dropped = true;
            _ = self.out.deinit(self.allocator);
            _ = self.chars.__cp_deinit();
    }

pub fn b(self: *Printer, bytes: []const u8) void {
            _ = bun.handleOom(self.out.appendSlice(self.allocator, bytes));
    }

pub fn color(self: *Printer, c: []const u8) void {
            if ((self.colors and (c.len > 0))) {
                _ = self.b(c);
            }
    }

pub fn num(self: *Printer, n: usize) void {
            var buf: [32]u8 = undefined;
            _ = &buf;
            const s = ((std.fmt.bufPrint((&buf), "{d}", .{ n })) catch unreachable);
            _ = self.b(s);
    }

pub fn flush(self: *Printer, writer: anytype) !void {
            if ((self.out.items.len > 0)) {
                _ = try writer.writeAll(self.out.items);
                _ = self.out.clearRetainingCapacity();
            }
    }

pub fn endRow(self: *Printer, writer: anytype) !void {
            _ = self.b("\n");
            if ((self.out.items.len >= FLUSH_AT)) {
                _ = try self.flush(writer);
            }
    }

pub fn prefix(self: *Printer, style: Style) void {
            _ = self.color(style.prefix_color);
            _ = self.b(style.prefix);
            _ = self.color(colors.reset);
    }

pub fn rows(self: *Printer, writer: anytype, text: []const u8, style: Style) !void {
            _ = self.prefix(style);
            _ = self.segment(text, style);
            _ = try self.endRow(writer);
    }

pub fn segment(self: *Printer, text: []const u8, style: Style) void {
            _ = self.color(style.text_color);
            var start: usize = 0;
            _ = &start;
            while (true) {
                var end: usize = text.len;
                _ = &end;
                if (bun.strings.indexOfCharUsize(text[start..], 10)) |idx| {
                    _ = &idx;
                    end = (start + idx);
                }
                const line = text[start..end];
                if ((line.len <= self.limit)) {
                    _ = self.b(line);
                } else {
                    _ = self.truncatedLine(line, style);
                }
                if ((end == text.len)) {
                    break;
                }
                _ = self.color(colors.reset);
                _ = self.b("\n");
                _ = self.prefix(style);
                _ = self.color(style.text_color);
                start = (end + 1);
            }
            _ = self.color(colors.reset);
    }

pub fn truncatedLine(self: *Printer, line: []const u8, style: Style) void {
            var head = self.config.truncate_context;
            _ = &head;
            var tail = (line.len - self.config.truncate_context);
            _ = &tail;
            while (((head > 0) and text_diff.isUtf8Cont(line, head))) {
                head = (head - 1);
            }
            while (text_diff.isUtf8Cont(line, tail)) {
                tail = (tail + 1);
            }
            _ = self.b(line[0..head]);
            _ = self.color(colors.reset);
            _ = self.color(colors.white);
            _ = self.b("... (");
            _ = self.num((tail - head));
            _ = self.b(" bytes truncated) ...");
            _ = self.color(colors.reset);
            _ = self.color(style.text_color);
            _ = self.b(line[tail..]);
    }

pub fn hunkHeader(self: *Printer, writer: anytype, original_line: usize, original_count: usize, changed_line: usize, changed_count: usize) !void {
            _ = self.color(colors.yellow);
            _ = self.b("@@ -");
            _ = self.num(original_line);
            _ = self.b(",");
            _ = self.num(original_count);
            _ = self.b(" +");
            _ = self.num(changed_line);
            _ = self.b(",");
            _ = self.num(changed_count);
            _ = self.b(" @@");
            _ = self.color(colors.reset);
            _ = try self.endRow(writer);
    }

pub fn nonemptySegment(self: *Printer, text: []const u8, style: Style) void {
            if ((text.len > 0)) {
                _ = self.segment(text, style);
            }
    }

pub fn highlighted(self: *Printer, text: []const u8, style: Style, whitespace_style: Style) void {
            if ((text.len == 0)) {
                return;
            }
            var all_ws = true;
            _ = &all_ws;
            for (cp_iter_slice(text)) |c| {
                _ = &c;
                if ((!isWhitespaceOrControl(c))) {
                    all_ws = false;
                    break;
                }
            }
            if (all_ws) {
                _ = self.segment(text, whitespace_style);
            } else {
                _ = self.segment(text, style);
            }
    }

pub fn modifiedWithoutHighlight(self: *Printer, writer: anytype, removed: []const u8, inserted: []const u8, rs: Style, is: Style, single_line: bool) !void {
            _ = self.prefix(rs);
            _ = self.segment(removed, style_removed);
            _ = self.b("\n");
            _ = self.prefix(is);
            _ = self.segment(inserted, style_inserted);
            if ((!single_line)) {
                _ = try self.endRow(writer);
            }
    }

pub fn modified(self: *Printer, writer: anytype, removed: []const u8, inserted: []const u8, single_line: bool) !void {
            const rs = (if (single_line) style_single_line_removed else style_removed);
            const is = (if (single_line) style_single_line_inserted else style_inserted);
            const larger = @max(removed.len, inserted.len);
            const smaller = @min(removed.len, inserted.len);
            if (((larger > 30) and ((smaller *| 3) < larger))) {
                return self.modifiedWithoutHighlight(writer, removed, inserted, rs, is, single_line);
            }
            if ((((!self.colors) and (maxLineLen(removed) <= self.limit)) and (maxLineLen(inserted) <= self.limit))) {
                return self.modifiedWithoutHighlight(writer, removed, inserted, rs, is, single_line);
            }
            const hunks = self.chars.diff(removed, inserted);
            var deleted_highlighted: usize = 0;
            _ = &deleted_highlighted;
            var inserted_highlighted: usize = 0;
            _ = &inserted_highlighted;
            for (cp_iter_slice(hunks)) |h| {
                _ = &h;
                deleted_highlighted = (deleted_highlighted + h.deleted());
                inserted_highlighted = (inserted_highlighted + h.inserted());
            }
            if (((((deleted_highlighted > 10) and (deleted_highlighted > ((removed.len / 3) * 2))) or ((inserted_highlighted > 10) and (inserted_highlighted > ((inserted.len / 3) * 2)))) or ((singleLinePair(removed, inserted) and (hunks.len > 32)) and ((hunks.len * 16) > smaller)))) {
                return self.modifiedWithoutHighlight(writer, removed, inserted, rs, is, single_line);
            }
            for (cp_iter_slice(hunks)) |h| {
                _ = &h;
                if ((((text_diff.isUtf8Cont(removed, h.a_lo) or text_diff.isUtf8Cont(removed, h.a_hi)) or text_diff.isUtf8Cont(inserted, h.b_lo)) or text_diff.isUtf8Cont(inserted, h.b_hi))) {
                    return self.modifiedWithoutHighlight(writer, removed, inserted, rs, is, single_line);
                }
            }
            _ = self.prefix(rs);
            var prev_a: usize = 0;
            _ = &prev_a;
            for (cp_iter_slice(hunks)) |h| {
                _ = &h;
                _ = self.nonemptySegment(removed[prev_a..h.a_lo], style_removed);
                _ = self.highlighted(removed[h.a_lo..h.a_hi], style_removed, style_removed_whitespace);
                prev_a = h.a_hi;
            }
            _ = self.nonemptySegment(removed[prev_a..], style_removed);
            _ = self.b("\n");
            _ = self.prefix(is);
            var prev_b: usize = 0;
            _ = &prev_b;
            for (cp_iter_slice(hunks)) |h| {
                _ = &h;
                _ = self.nonemptySegment(inserted[prev_b..h.b_lo], style_inserted);
                _ = self.highlighted(inserted[h.b_lo..h.b_hi], style_inserted, style_inserted_whitespace);
                prev_b = h.b_hi;
            }
            _ = self.nonemptySegment(inserted[prev_b..], style_inserted);
            if ((!single_line)) {
                _ = try self.endRow(writer);
            }
    }

pub fn diff(self: *Printer, writer: anytype, expected: []const u8, received: []const u8, hunks: []const Hunk) !void {
            const end = expected.len;
            var segments = std.ArrayListUnmanaged(Segment).empty;
            _ = &segments;
            defer {
            _ = segments.deinit(self.allocator);
            }
            _ = bun.handleOom(segments.ensureTotalCapacity(self.allocator, ((hunks.len * 3) + 2)));
            var prev_a: usize = 0;
            _ = &prev_a;
            var i: usize = 0;
            _ = &i;
            for (cp_iter_slice(hunks)) |h| {
                _ = &h;
                defer {
                i = (i + 1);
                }
                if ((h.a_lo > prev_a)) {
                    const tl = segRange(expected[prev_a..h.a_lo], false);
                    _ = bun.handleOom(segments.append(self.allocator, Segment{ .equal = tl }));
                }
                const last = (((i + 1) == hunks.len) and (h.a_hi == end));
                const rem = segRange(expected[h.a_lo..h.a_hi], last);
                const ins = segRange(received[h.b_lo..h.b_hi], last);
                if (((h.deleted() > 0) and (h.inserted() > 0))) {
                    _ = bun.handleOom(segments.append(self.allocator, Segment{ .modified = ModifiedSeg{ .removed = rem.text, .inserted = ins.text, .removed_lines = rem.lines, .inserted_lines = ins.lines } }));
                } else {
                    if ((h.deleted() > 0)) {
                        _ = bun.handleOom(segments.append(self.allocator, Segment{ .removed = rem }));
                    } else {
                        _ = bun.handleOom(segments.append(self.allocator, Segment{ .inserted = ins }));
                    }
                }
                prev_a = h.a_hi;
            }
            if ((prev_a < end)) {
                const tl = segRange(expected[prev_a..], true);
                _ = bun.handleOom(segments.append(self.allocator, Segment{ .equal = tl }));
            }
            const chunked = ((expected.len > self.config.min_bytes_before_chunking) or (received.len > self.config.min_bytes_before_chunking));
            if (chunked) {
                const ctx = self.config.chunk_context_lines;
                var out_segs = std.ArrayListUnmanaged(Segment).empty;
                _ = &out_segs;
                _ = bun.handleOom(out_segs.ensureTotalCapacity(self.allocator, ((segments.items.len + hunks.len) + 2)));
                const n = segments.items.len;
                var si: usize = 0;
                _ = &si;
                for (segments.items) |seg| {
                    _ = &seg;
                    defer {
                    si = (si + 1);
                    }
                    switch (seg) {
.equal => |eq| {
const keep_head = (if ((si > 0)) ctx else 0);
                    const keep_tail = (if (((si + 1) < n)) ctx else 0);
                    if ((eq.lines <= (keep_head + keep_tail))) {
                        _ = bun.handleOom(out_segs.append(self.allocator, seg));
                        continue;
                    }
                    if ((keep_head > 0)) {
                        const head_end = (afterNthNewline(eq.text, keep_head)).?;
                        _ = bun.handleOom(out_segs.append(self.allocator, Segment{ .equal = TextLines{ .text = eq.text[0..(head_end - 1)], .lines = keep_head } }));
                    }
                    _ = bun.handleOom(out_segs.append(self.allocator, Segment{ .skipped = ((eq.lines - keep_head) - keep_tail) }));
                    if ((keep_tail > 0)) {
                        const tail_start = (startOfLastNLines(eq.text, keep_tail)).?;
                        _ = bun.handleOom(out_segs.append(self.allocator, Segment{ .equal = TextLines{ .text = eq.text[tail_start..], .lines = keep_tail } }));
                    }
},
else => {
_ = bun.handleOom(out_segs.append(self.allocator, seg));
},
}
                }
                _ = segments.deinit(self.allocator);
                segments = out_segs;
            }
            _ = try self.renderSegments(writer, segments.items);
    }

