original = (original + eq.lines);
                        changed = (changed + eq.lines);
},
.removed => |r| {
original = (original + r.lines);
},
.inserted => |ins| {
changed = (changed + ins.lines);
},
.modified => |m| {
original = (original + m.removed_lines);
                        changed = (changed + m.inserted_lines);
},
}
                    }
                    _ = try self.hunkHeader(writer, removed_line_number, original, inserted_line_number, changed);
                }
                switch (seg) {
.equal => |eq| {
_ = try self.rows(writer, eq.text, style_equal);
                removed_line_number = (removed_line_number + eq.lines);
                inserted_line_number = (inserted_line_number + eq.lines);
},
.removed => |r| {
_ = try self.rows(writer, r.text, style_removed);
                removed_line_number = (removed_line_number + r.lines);
                removed_diff_lines = (removed_diff_lines + r.lines);
},
.inserted => |ins| {
_ = try self.rows(writer, ins.text, style_inserted);
                inserted_line_number = (inserted_line_number + ins.lines);
                inserted_diff_lines = (inserted_diff_lines + ins.lines);
},
.modified => |m| {
_ = try self.modified(writer, m.removed, m.inserted, false);
                removed_line_number = (removed_line_number + m.removed_lines);
                inserted_line_number = (inserted_line_number + m.inserted_lines);
                removed_diff_lines = (removed_diff_lines + m.removed_lines);
                inserted_diff_lines = (inserted_diff_lines + m.inserted_lines);
},
.skipped => {
_ = unreachable;
},
}
            }
            _ = try self.endRow(writer);
            _ = self.color(style_removed.prefix_color);
            _ = self.b("- Expected  - ");
            _ = self.num(removed_diff_lines);
            _ = self.color(colors.reset);
            _ = self.b("\n");
            _ = self.color(style_inserted.prefix_color);
            _ = self.b("+ Received  + ");
            _ = self.num(inserted_diff_lines);
            _ = self.color(colors.reset);
    }
};

const Hunk = text_diff.Hunk;
const FLUSH_AT: usize = cp_shl(64, 10);
const style_inserted = Style{ .prefix = "+ ", .prefix_color = colors.red, .text_color = colors.red };
const style_removed = Style{ .prefix = "- ", .prefix_color = colors.green, .text_color = colors.green };
const style_inserted_whitespace = Style{ .prefix = "+ ", .prefix_color = colors.red, .text_color = (colors.red ++ colors.invert) };
const style_removed_whitespace = Style{ .prefix = "- ", .prefix_color = colors.green, .text_color = (colors.green ++ colors.invert) };
const style_equal = Style{ .prefix = "  ", .prefix_color = "", .text_color = colors.dim };
const style_single_line_inserted = Style{ .prefix = "Received: ", .prefix_color = "", .text_color = colors.red };
const style_single_line_removed = Style{ .prefix = "Expected: ", .prefix_color = "", .text_color = colors.green };

pub fn lineCount(text: []const u8) usize {
        return (bun.strings.countChar(text, 10) + 1);
}

pub fn singleLinePair(a: []const u8, b: []const u8) bool {
        return ((bun.strings.indexOfCharUsize(a, 10) == null) and (bun.strings.indexOfCharUsize(b, 10) == null));
}

pub fn maxLineLen(text: []const u8) usize {
        var max_len: usize = 0;
        _ = &max_len;
        var start: usize = 0;
        _ = &start;
        while (true) {
            var end: usize = text.len;
            _ = &end;
            if (bun.strings.indexOfCharUsize(text[start..], 10)) |idx| {
                _ = &idx;
                end = (start + idx);
            }
            max_len = @max(max_len, (end - start));
            if ((end == text.len)) {
                return max_len;
            }
            start = (end + 1);
        }
}

pub fn afterNthNewline(text: []const u8, n: usize) ?usize {
        var at: usize = 0;
        _ = &at;
        var i: usize = 0;
        _ = &i;
        while ((i < n)) : (i = (i + 1)) {
            if (bun.strings.indexOfCharUsize(text[at..], 10)) |idx| {
                _ = &idx;
                at = (at + (idx + 1));
            } else {
                return null;
            }
        }
        return at;
}

pub fn startOfLastNLines(text: []const u8, n: usize) ?usize {
        var at: usize = text.len;
        _ = &at;
        var i: usize = 0;
        _ = &i;
        while ((i < n)) : (i = (i + 1)) {
            if (bun.strings.lastIndexOfChar(text[0..at], 10)) |idx| {
                _ = &idx;
                at = idx;
            } else {
                return null;
            }
        }
        return (at + 1);
}

pub fn segRange(text: []const u8, last: bool) TextLines {
        var shown = text;
        _ = &shown;
        if (((!last) and std.mem.endsWith(u8, text, "\n"))) {
            shown = text[0..(text.len - 1)];
        }
        return TextLines{ .text = shown, .lines = lineCount(shown) };
}

pub fn isWhitespaceOrControl(c: u8) bool {
        return ((c <= 32) or (c == 127));
}

pub fn printHunkHeader(writer: anytype, config: DiffConfig, original_line_number: usize, original_line_count: usize, changed_line_number: usize, changed_line_count: usize) !void {
        if (config.enable_ansi_colors) {
            _ = try writer.print("{s}@@ -{},{} +{},{} @@{s}\n", .{ colors.yellow, original_line_number, original_line_count, changed_line_number, changed_line_count, colors.reset });
        } else {
            _ = try writer.print("@@ -{},{} +{},{} @@\n", .{ original_line_number, original_line_count, changed_line_number, changed_line_count });
        }
}

pub fn printDiffMain(allocator: std.mem.Allocator, not: bool, received_slice: []const u8, expected_slice: []const u8, writer: anytype, config: DiffConfig) std.Io.Writer.Error!void {
        if (not) {
            if (config.enable_ansi_colors) {
                _ = try writer.print(((("Expected: not " ++ colors.red) ++ "{s}") ++ colors.reset), .{ expected_slice });
            } else {
                _ = try writer.print("Expected: not {s}", .{ expected_slice });
            }
            return;
        }
        const cap = @min((((received_slice.len + expected_slice.len) * 2) + 256), (FLUSH_AT * 2));
        var p = Printer.init(allocator, cap, config);
        _ = &p;
        var __p_moved = false; _ = &__p_moved;
        defer if (!__p_moved) { __p_moved = true; const __T = @TypeOf(p); if (@typeInfo(__T) == .optional) { if (p) |__cp_opt_v| { const __OptT = @TypeOf(__cp_opt_v); if (@typeInfo(__OptT) == .pointer and @typeInfo(__OptT).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__OptT).pointer), "is_const")) !@typeInfo(__OptT).pointer.is_const else !@typeInfo(__OptT).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__OptT).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { __cp_opt_v.__cp_deinit(); } } else if (@typeInfo(__OptT) == .@"struct" and @hasDecl(__OptT, "__cp_deinit")) { var _drop_val = __cp_opt_v; _drop_val.__cp_deinit(); } } } else if (@typeInfo(__T) == .pointer and @typeInfo(__T).pointer.size == .one and (if (@hasField(@TypeOf(@typeInfo(__T).pointer), "is_const")) !@typeInfo(__T).pointer.is_const else !@typeInfo(__T).pointer.attrs.@"const")) { const __CpChild = @typeInfo(__T).pointer.child; if (@typeInfo(__CpChild) == .@"struct" and @hasDecl(__CpChild, "__cp_deinit")) { p.__cp_deinit(); } } else if (@typeInfo(__T) == .@"struct" and @hasDecl(__T, "__cp_deinit")) { var _drop_val = p; _drop_val.__cp_deinit(); } };
        defer {
        _ = (blk: { if (!__p_moved) { __p_moved = true; p.__cp_deinit(); } break :blk {}; });
        }
        if (singleLinePair(received_slice, expected_slice)) {
            _ = try p.modified(writer, expected_slice, received_slice, true);
        } else {
            var hunks = text_diff.diffLines(allocator, expected_slice, received_slice);
            _ = &hunks;
            defer {
            _ = hunks.deinit(allocator);
            }
            _ = try p.diff(writer, expected_slice, received_slice, hunks.items);
        }
        _ = try p.flush(writer);
}
